Here are comprehensive pytest unit tests covering happy paths, edge cases, and error cases:

```python
import pytest


def title_case(s: str) -> str:
    return ' '.join(word.capitalize() for word in s.split())


class TestTitleCaseHappyPath:
    @pytest.mark.parametrize(
        "input_val,expected",
        [
            ("hello world", "Hello World"),
            ("hello", "Hello"),
            ("a b c", "A B C"),
            ("the quick brown fox", "The Quick Brown Fox"),
            ("HELLO WORLD", "Hello World"),
            ("hElLo WoRlD", "Hello World"),
            ("they're here", "They're Here"),
            ("hello, world!", "Hello, World!"),
        ],
    )
    def test_standard_cases(self, input_val, expected):
        assert title_case(input_val) == expected

    def test_unicode_characters(self):
        assert title_case("über naïve résumé") == "Über Naïve Résumé"


class TestTitleCaseEdgeCases:
    def test_empty_string(self):
        assert title_case("") == ""

    def test_whitespace_only(self):
        assert title_case("   ") == ""
        assert title_case("\t\n\r ") == ""

    def test_single_character(self):
        assert title_case("a") == "A"
        assert title_case("A") == "A"
        assert title_case("z") == "Z"

    def test_multiple_spaces_between_words(self):
        assert title_case("hello    world") == "Hello World"
        assert title_case("a\t\t\tb") == "A B"

    def test_leading_and_trailing_whitespace(self):
        assert title_case("  hello world  ") == "Hello World"
        assert title_case("\n\thello world\r") == "Hello World"

    def test_mixed_whitespace_characters(self):
        assert title_case("hello\tworld\nfoo\rbar") == "Hello World Foo Bar"

    def test_numbers_and_alphanumeric(self):
        assert title_case("42abc abc42") == "42abc Abc42"
        assert title_case("123 456") == "123 456"
        assert title_case("3d printer") == "3d Printer"

    def test_punctuation_and_symbols(self):
        # capitalize() only affects the first cased character;
        # punctuation attached to words is preserved
        assert title_case("-hello +world") == "-hello +world"
        assert title_case("mcdonald's") == "Mcdonald's"
        assert title_case("hello!!!") == "Hello!!!"

    def test_apostrophe_behavior(self):
        # capitalize() lowercases characters after the first one
        assert title_case("O'REILLY") == "O'reilly"


class TestTitleCaseErrorCases:
    def test_none_raises_attribute_error(self):
        with pytest.raises(AttributeError):
            title_case(None)

    def test_integer_raises_attribute_error(self):
        with pytest.raises(AttributeError):
            title_case(42)

    @pytest.mark.parametrize("invalid_input", [
        ["hello", "world"],
        {"hello": "world"},
        (1, 2, 3),
    ])
    def test_non_string_iterables_raise_attribute_error(self, invalid_input):
        with pytest.raises(AttributeError):
            title_case(invalid_input)
```

### Key coverage notes:
- **Happy path:** Typical sentences, mixed casing, punctuation attached to words, and Unicode.
- **Edge cases:** Empty strings, whitespace-only strings, single characters, multiple/leading/trailing whitespace (which Python's `split()` collapses), and numbers.
- **Error cases:** Since the function lacks runtime type validation, non-string inputs (`None`, `int`, `list`, etc.) raise `AttributeError` when calling `.split()`. Tests verify these failures explicitly.
